import java.util.Scanner;

public class Main {
    static final int N = 1000005;
    static final long MOD = 1000000007L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p_value = sc.nextInt();
        int k_value = sc.nextInt();

        if (k_value == 0) {
            long result = 1;
            for (int i = 1; i < p_value; ++i) {
                result = (result * p_value) % MOD;
            }
            System.out.println(result);
            sc.close();
            return;
        }

        int[] a = new int[N];
        boolean[] visited = new boolean[N];

        for (int i = 1; i < p_value; ++i) {
            a[i] = (int)((long)k_value * i % p_value);
        }

        long answer = 1;
        for (int i = 0; i < p_value; ++i) {
            if (!visited[i]) {
                int cycle_size = 0;
                int j = i;
                long tmp_product = 1;
                while (!visited[j]) {
                    visited[j] = true;
                    j = a[j];
                    cycle_size++;
                    tmp_product = (tmp_product * k_value) % p_value;
                }
                if (cycle_size == 1) {
                    int count = (k_value == 1) ? p_value : 1;
                    answer = (answer * count) % MOD;
                } else {
                    // In Java, no assert, but we can throw an exception if needed
                    if (tmp_product != 1) {
                        // This should not happen as per original code
                        throw new RuntimeException("Assertion failed: tmp_product != 1");
                    }
                    answer = (answer * p_value) % MOD;
                }
            }
        }
        System.out.println(answer);
        sc.close();
    }
}
